// Crusaders Mainframe — a constant table kept in FLASH on the ESP8266, read a
// row at a time into RAM.
//
// WHY
// ---
// The ESP8266 core places `.rodata` in RAM: every const table in lib/ is heap
// the bridge does not have (device-api.md §13's floor is 24 KB). The screen
// table alone is 2.3 KB. On the ESP8266 a table marked BRIDGE_FLASH lives in
// flash, where only aligned 32-bit loads are legal — so it is never read in
// place, only copied out whole with memcpy_P. On every other build (the host
// test runner, the simulator) both are no-ops.
//
// No Arduino headers (pgmspace.h is the SDK's). C++11-valid.

#ifndef CRUSADERS_BRIDGELOGIC_FLASHTABLE_H
#define CRUSADERS_BRIDGELOGIC_FLASHTABLE_H

#include <stddef.h>
#include <string.h>

#if defined(ARDUINO_ARCH_ESP8266)
#include <pgmspace.h>
#define BRIDGE_FLASH PROGMEM
#else
#define BRIDGE_FLASH
#endif

namespace bridgelogic {

/// Copies `len` bytes of a BRIDGE_FLASH table out into RAM.
inline void flashCopy(void* out, const void* table, size_t len) {
#if defined(ARDUINO_ARCH_ESP8266)
  memcpy_P(out, table, len);
#else
  memcpy(out, table, len);
#endif
}

} // namespace bridgelogic

#endif // CRUSADERS_BRIDGELOGIC_FLASHTABLE_H
